<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';const router=useRouter(),step=ref(1),name=ref(''),email=ref(''),password=ref(''),error=ref(''),environment=ref<any>({});onMounted(async()=>{environment.value=(await (await fetch('/api/v1/setup/status')).json()).infrastructure||{}});async function submit(){const r=await fetch('/api/v1/setup/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value,email:email.value,password:password.value})});if(r.ok)step.value=4;else error.value='Revise os dados informados.'}</script>
<template><div class="center"><p class="kicker">STEP {{step}} OF 4 · STACKHOST SETUP</p><div v-if="step===1"><h1>Build your control plane.</h1><p class="muted">A calm, reliable home for your infrastructure.</p><div class="empty"><h2>Welcome to StackHost</h2><p>We will create your administrator and check the environment in a few seconds.</p><button class="primary" @click="step=2">Get started</button></div></div><div v-else-if="step===2"><h1>Create your administrator.</h1><p class="muted">This account will manage this local environment.</p><form @submit.prevent="step=3"><label>Name<input v-model="name" required /></label><label>Email<input v-model="email" type="email" required /></label><label>Password<input v-model="password" type="password" minlength="8" required /></label><button class="primary">Continue</button></form></div><div v-else-if="step===3"><h1>Check your environment.</h1><p class="muted">Docker is optional for onboarding and can be connected later.</p><div class="status"><span class="dot"></span><div><strong>{{environment.available?'Docker connected':'Docker optional'}}</strong><p>{{environment.available?`Docker ${environment.engine_version} detected`:'The panel can continue without Docker.'}}</p></div><span class="pill">{{environment.swarm?.active?'Swarm ready':'No Swarm'}}</span></div><button class="primary" @click="submit">Create administrator</button></div><div v-else><h1>You are ready.</h1><p class="muted">Your administrator account is active.</p><div class="empty"><h2>Welcome aboard</h2><p>Open the dashboard to start organizing your projects.</p><button class="primary" @click="router.push('/')">Open dashboard</button></div></div><p class="error">{{error}}</p></div></template>
